import json
with open('/app/resources/treasury_bulletin_1960_01.json', 'r') as f:
    data = json.load(f)

# Look for exchange rate data
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'exchange' in k.lower() or 'cad' in k.lower() or 'canada' in k.lower():
                print(f'{path}.{k}: {v}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:5]):
            search(item, f'{path}[{i}]')

search(data)
