import urllib.request

# One more URL variation for historical data from the Federal Reserve
urls_to_try = [
    'https://www.federalreserve.gov/releases/h10/m3m_canad_hist.txt',
    'https://www.federalreserve.gov/ releases/h10/frames.cfm?m3m-200610',
]

for url in urls_to_try:
    try:
        req = urllib.request.Request(url)
        req.add_header('User-Agent', 'Mozilla/5.0')
        with urllib.request.urlopen(req) as response:
            data = response.read().decode('utf-8', errors='ignore')
            if '1959' in data:
                print(f"URL {url[:40]} has 1959 data")
                # Find the relevant section
                lines = data.split('\n')
                for line in lines:
                    if '1959' in line and '12' in line:
                        print(f"  {line.strip()}")
    except Exception as e:
        print(f"URL failed: {e}")
